-- ============================================================
-- TRIGGER FUNCTION: fires after INSERT on employees.salary
-- Logs a 'new' alert for any salary > 120,000
-- ============================================================
CREATE OR REPLACE FUNCTION employees.trg_high_salary_alert()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.amount > 120000 THEN
        INSERT INTO employees.salary_alerts
            (employee_id, salary_amount, alert_date, status)
        VALUES
            (NEW.employee_id, NEW.amount, CURRENT_DATE, 'new');
    END IF;
    RETURN NEW;
END;
$$;

-- Attach the trigger to the salary table (AFTER INSERT)
DROP TRIGGER IF EXISTS high_salary_alert ON employees.salary;

CREATE TRIGGER high_salary_alert
    AFTER INSERT ON employees.salary
    FOR EACH ROW
    EXECUTE FUNCTION employees.trg_high_salary_alert();
"}

