-- PERFORMANCE INDEXES
-- ============================================================

-- Index 1: salary_alerts.status for fast alert-queue processing
CREATE INDEX IF NOT EXISTS idx_salary_alerts_status
    ON employees.salary_alerts (status);

-- Index 2: composite index on monthly_reports for trend queries
CREATE INDEX IF NOT EXISTS idx_monthly_reports_date_deptcount
    ON employees.monthly_reports (report_date, department_count);

-- Bonus: additional useful indexes for the core tables
-- (speed up the materialized view refreshes and trigger lookups)
CREATE INDEX IF NOT EXISTS idx_salary_emp_todate
    ON employees.salary (employee_id, to_date);

CREATE INDEX IF NOT EXISTS idx_dept_emp_todate
    ON employees.department_employee (employee_id, to_date);

CREATE INDEX IF NOT EXISTS idx_dept_mgr_todate
    ON employees.department_manager (department_id, to_date);
